rows=[]
def add(qid,no,title,stem,opts,answer,student,explanation,analyses,trap,fig=None):
 q={'id':f'q-{qid}','sourceId':'src-more-051','subject':'Math','title':f'數學第{no}題｜{title}','chapter':'綜合','volume':'綜合','date':'2026-10-30','dateLabel':'首次出題日期','addedAt':'2026-10-31','question':stem+ ('\n'+'\n'.join(f'({c}) {o}' for c,o in zip('ABCD',opts)) if opts else ''),'answer':f'({answer}) {opts["ABCD".index(answer)]}' if opts else answer,'explanation':explanation,'trap':trap,'tags':[title],'verification':'原卷逐題核對','verificationNote':'完整原題、全部選項與必要圖已實看；代數獨立驗算。日期採原始使用者出題日期，不冒稱考試日期。','images':[f'assets/originals/q-{qid}-original-a-math.webp'],'questionFigures':[{'src':f'assets/originals/q-{qid}-given-a-math.webp','alt':fig,'caption':'原卷作答附圖；與必要內容重疊的原筆跡依使用者規則保留。'}] if fig else [],'explanationFigures':[],'tables':[],'passage':'','sourceLabel':f'分享原卷｜第{no}題','studentAnswer':student,'correctOption':answer if opts else '', 'optionAnalysis':[{'label':c,'text':o,'wordClass':'應選' if c==answer else '不選','meaning':'','explanation':a} for c,o,a in zip('ABCD',opts,analyses)],'contentStatus':'完整原題','status':'todo','starred':False,'notes':''};(P/'questions'/f'q-{qid}.json').write_text(json.dumps(q,ensure_ascii=False,indent=2)+'\n');rows.append({'id':q['id'],'originalNumber':str(no)})
add(890,5,'二次方程式的實根條件','若一元二次方程式2x²−ax＋5＝0有解，且a為整數，則下列何者不可能為a的值？',['−9','−7','8','6'],'D','B','國中此題的「有解」指有實數解。判別式Δ＝(−a)²−4×2×5＝a²−40，因此須a²≥40。因為6²＝36＜40、7²＝49＞40，整數a須a≤−7或a≥7。逐項代入，−9、−7、8的判別式分別為41、9、24，皆非負；6的判別式為−4，沒有實數解，故選D。也可配方成(4x−a)²＝a²−40，左邊平方不能為負，得到相同條件。',['a＝−9時，Δ＝81−40＝41＞0，有實根。','a＝−7時，Δ＝49−40＝9＞0，有實根。','a＝8時，Δ＝64−40＝24＞0，有實根。','a＝6時，Δ＝36−40＝−4＜0，沒有實數解。'],'有實數解須判別式非負；負的a也要平方後判斷。')
add(892,8,'整係數因式分解的配對','若x²＋kx−12可被因式分解成兩個一次式的乘積，則下列何者不可能為k的值？',['11','−7','4','−1'],'B','C','依國中整係數因式分解的題型慣例，設x²＋kx−12＝(x＋m)(x＋n)，其中m、n為整數，則mn＝−12、m＋n＝k。乘積負，兩數異號；正因數配對是1與12、2與6、3與4，所以k可能為±11、±4、±1。四項中只有−7不在其中，選B。其餘三項可分別寫成(x＋12)(x−1)、(x＋6)(x−2)、(x＋3)(x−4)。這裡的「不能」限定本題國中整係數分解範圍，不是宣稱實數係數的一次式也完全不能表示。',['k＝11時，可分解為(x＋12)(x−1)。','不存在乘積−12且和−7的整數配對。','k＝4時，可分解為(x＋6)(x−2)。','k＝−1時，可分解為(x＋3)(x−4)。'],'先同時檢查兩常數的乘積與和，不只看某一組相減。')
add(894,10,'看錯係數後留下的線索','甲、乙兩人解同一方程式x²＋ax＋b＝0，甲看錯x項係數，解得x＝−2或3；乙看錯常數項，解得x＝4或−5，則a−b之值為何？',['7','−7','−19','−21'],'A','D','甲只看錯x項係數，所以常數b仍正確。由根−2、3重建(x＋2)(x−3)＝x²−x−6，可知b＝−6。乙只看錯常數項，所以一次項係數a仍正確。由根4、−5重建(x−4)(x＋5)＝x²＋x−20，可知a＝1。因此a−b＝1−(−6)＝7，選A。不要把甲、乙各自看錯部分的數值都拿來當原方程式係數。',['a＝1、b＝−6，故a−b＝7。','−7是將所求差的方向或符號弄反。','−19可由混用乙看錯的常數−20得到，不能用作原b。','−21也混入錯誤常數，沒有保留各人讀對的係數。'],'誰看錯哪一項，就只留下他讀對那一項的資訊。')
add(896,20,'剩餘面積與質數條件','如右圖，大銘在一張邊長為4x＋3的正方形紙卡內剪下一邊長為3x＋5的正方形，若x為正整數，且剩下的紙卡部分面積為質數P，則P之值為何？',['19','23','29','31'],'C','A','外正方形邊長必須大於內正方形，故4x＋3＞3x＋5，得x＞2。剩餘面積P＝(4x＋3)²−(3x＋5)²＝[(4x＋3)−(3x＋5)][(4x＋3)＋(3x＋5)]＝(x−2)(7x＋8)。x為正整數且x＞2，兩因數都是正整數，而7x＋8＞1。乘積為質數時，只能讓較小因數x−2＝1，因此x＝3、P＝29。回代外邊15、內邊14，225−196＝29，與選C相符。',['質數條件推出x＝3，實際面積不是19。','回代x＝3所得225−196不是23。','x＝3時，P＝(3−2)(21＋8)＝29。','31不是本題幾何及整數條件推出的剩餘面積。'],'先保證內邊小於外邊、因數為正，再用質數只有1與自身兩個正因數。',fig='原卷外邊4x＋3、內邊3x＋5的兩個正方形。')
add(898,'2(2)','拼接長方形的共邊與總長','如右圖，將兩個長方形ABCD和CDEF拼成一個大的長方形ABFE，已知長方形ABCD的面積為6x²−13x−5，長方形CDEF面積為12x²−14x−6，又CD＝3x＋k，若AB、AD、DE均為x的一次多項式，且係數均為整數，試回答下列問題：\n(2) AE＋BF＝？（3分）',[],'AE＋BF＝12x−22','30（原卷手寫後被訂正）','兩個小長方形共用邊CD，也有AB＝CD＝EF。先分解兩面積：6x²−13x−5＝(3x＋1)(2x−5)，12x²−14x−6＝(3x＋1)(4x−6)。共邊形式是3x＋k，故共同因式取3x＋1，得到AD＝2x−5、DE＝4x−6。於是AE＝AD＋DE＝6x−11；大長方形對邊相等，BF＝AE，所以AE＋BF＝2(6x−11)＝12x−22。本次只收入使用者問的第(2)小題；求出共邊是必要中間步驟，沒有另外新增第(1)小題。幾何邊長須為正，此處取符合題圖長方形的x＞5/2，不將負的式值畫成實際邊長。',[],'先找兩塊面積的共因式當共邊，再求兩段寬之和；AE＋BF是總寬的兩倍。',fig='原卷兩個長方形ABCD、CDEF沿CD拼成ABFE，保留各頂點與重疊的原手寫筆跡。')
add(900,5,'兩組等差中項','若a與b的等差中項為5，a＋b與2a−b的等差中項為18，則a−b之值為何？',['10','12','14','16'],'C','B','兩數的等差中項是它們的平均。由(a＋b)/2＝5，得到a＋b＝10。第二組由[(a＋b)＋(2a−b)]/2＝18，合併b與−b後為3a/2＝18，所以a＝12。再由a＋b＝10，得b＝−2，因此a−b＝12−(−2)＝14，選C。回代第二組兩端為10與26，平均確為18。',['10是a＋b，不是題目要的a−b。','12是a，不是a−b。','a＝12、b＝−2，差為14。','16不符合兩組等差中項條件。'],'等差中項是平均數；求得負的b後，a−b要減去整個負數。')
add(902,6,'等比數列的隔項與倍乘','若將等比數列a₁，−35，a₃，−315，a₅，……，a₇的各項乘上(−5)，則新數列的公比為何？',['±3','−3','±15','−15'],'A','C','已知−35是第2項，−315是第4項，兩者相隔2次公比。設原公比r，則(−315)/(−35)＝r²＝9，所以r＝3或−3，不能只留其中一個。每項同乘非零常數−5後，相鄰兩項的新比值為[(−5)aₙ₊₁]/[(−5)aₙ]＝aₙ₊₁/aₙ＝r，公比不變。因此新公比也為±3，選A。乘的是各項，不是把公比再乘−5。',['隔2項得r²＝9，且整列同乘−5不改公比，故±3。','只保留負公比，漏掉r＝3的可能。','把各項倍乘錯當成公比倍乘，且倍率處理錯誤。','把各項乘−5錯誤套用到公比，並漏掉另一種符號。'],'相隔2次公比要平方；各項同乘非零數，公比保持不變。')
add(904,10,'等差數列的項數間隔','已知一等差數列的首項為−1，第6項為(−1)⁶，則第3項為何？',['−1','−0.2','1.2','3'],'B','A','先算第6項給定的數值：(−1)⁶＝1。題目說的是等差數列，不是說每一項都等於(−1)的項數次方。第1項到第6項共有5個公差，所以−1＋5d＝1，得d＝2/5＝0.4。第3項比首項多2個公差，a₃＝−1＋2×0.4＝−0.2，選B。六項依序為−1、−0.6、−0.2、0.2、0.6、1，可直接回查首末兩項。',['−1是首項，不能把(−1)ⁿ當成這個等差數列的通式。','5個公差合計2，d＝0.4，第3項為−0.2。','1.2只是3個0.4，既沒對齊間隔也漏掉首項。','3不符合首項−1、第6項1的等差條件。'],'項數6不代表6段；首項至第6項只有5個公差。')
add(906,12,'插入項的數量與總和','在−7與31之間插入n個數，使其成為一等差數列。若插入的n個數之總和為96，則n的值為何？',['8','7','6','5'],'A','C','整個等差數列包括兩個端點及插入的n項，共n＋2項。首末兩項的平均為(−7＋31)/2＝12，所以全部項的總和為12(n＋2)。只算插入項時，應扣掉兩端的和−7＋31＝24，因此插入項總和＝12(n＋2)−24＝12n。由12n＝96，得n＝8，選A。回代有10項、9個間隔，公差d＝38/9；插入第1項與最後1項之和仍為24，8項平均12，合計96。',['8項的總和為12×8＝96，符合。','7項依相同首末端點的平均計算，和為84。','6項的和為72，不是96。','5項的和為60，不是96。'],'插入n項不是總共有n項；兩端不包含在96裡。')
add(908,15,'十字方格的等差中項','如右圖，橫列有7個方格，直行有4個方格。若在每個方格內填入一個數，使橫列的數由左到右成等差數列，且直行的數由上到下成等差數列，則x＋y之值為何？',['−12','−10','−8','−6'],'A','D','先看直行：由上到下4格，首項−10、末項2，共3個公差，故d＝[2−(−10)]/3＝4。交叉格是直行第2格，所以填−10＋4＝−6。再看橫列7格，交叉格恰是第4格，也就是正中央；等差數列對稱兩項的和等於中項的2倍。因此最左x與最右y相加為2×(−6)＝−12，選A。不必知道橫列公差，也不能把直行4格誤算成4個間隔。',['交叉中項−6，左右兩端和為−12。','−10是直行首格，並不是橫列兩端和。','可能來自將直行間隔數誤算，與題設不合。','−6只是交叉格中項；x＋y須再乘2。'],'直行交叉格是第2格；橫列交叉格是7格的正中央第4格。',fig='原卷7格橫列與4格直行十字圖，頂格−10、底格2，左右端為x、y；中央及下方手寫−6、−2依使用者規則保留。')
(P/'question-plan.json').write_text(json.dumps({'sourceId':'src-more-051','worker':'/root/comic_lane_3','questionIds':[x['id'] for x in rows],'items':rows,'count':10,'trueGroups':[],'excluded':'只使用者明示10道原問，原2只問(2)，未擴收同頁其他題。'},ensure_ascii=False,indent=2)+'\n');print('10 math drafts')
